SELECT generico5.categoria AS categoria FROM generico5 WHERE ((generico5.anunciante IN ('BANTRAB/TODOTICKET', 'TODOTICKET', 'TODOTICKET.COM')) AND (CAST(EXTRACT(YEAR FROM generico5.fecha) AS SIGNED) >= 2010) AND (CAST(EXTRACT(YEAR FROM generico5.fecha) AS SIGNED) <= 2015) AND (generico5.medio = 'TELEVISION NACIONAL') AND ((CAST(EXTRACT(MONTH FROM generico5.fecha) AS SIGNED) IS NULL) OR ((CAST(EXTRACT(MONTH FROM generico5.fecha) AS SIGNED) >= 2) AND (CAST(EXTRACT(MONTH FROM generico5.fecha) AS SIGNED) <= 12))) AND (CAST(EXTRACT(YEAR FROM generico5.fecha) AS SIGNED) = 2015)) GROUP BY generico5.categoria;
